import { agents } from '@genkit-ai/middleware';
import { FileSessionStore, z } from 'genkit/beta';
import { ai } from './ai.js';
import { createRefund } from './db.js';
import { lookupOrder } from './tools.js';

const store = new FileSessionStore('.genkit/sessions');

const issueRefund = ai.defineTool(
  {
    name: 'issueRefund',
    description: 'Refunds an amount to the customer for an order. Only call this after approveRefund returned approved.',
    inputSchema: z.object({ orderId: z.string(), amount: z.number() }),
    outputSchema: z.object({ refundId: z.string() }),
  },
  async ({ orderId, amount }) => ({ refundId: createRefund(orderId, amount) }),
);

const approveRefund = ai.defineInterrupt({
  name: 'approveRefund',
  description: 'Asks a human to approve a refund before it is issued.',
  inputSchema: z.object({ orderId: z.string(), amount: z.number(), reason: z.string() }),
  outputSchema: z.object({ approved: z.boolean(), note: z.string().optional() }),
});

/** Answers order status questions. */
export const orderAgent = ai.defineAgent({
  name: 'orderAgent',
  description: 'Answers questions about an order: its status, delivery date, tracking code and total.',
  system:
    'You are the Northwind Supplies order desk. Answer questions about orders using the lookupOrder tool. ' +
    'Quote the status, ETA and tracking code exactly as the tool returns them. If an order is not found, say so.',
  tools: [lookupOrder],
  maxTurns: 4,
});

/** Handles refund requests and pauses for human approval before refunding. */
export const refundAgent = ai.defineAgent({
  name: 'refundAgent',
  description: 'Handles refund requests for an order. Refunds need human approval.',
  system: 'Look up the order, then call approveRefund, then issueRefund only if approved. Never refund without approval.',
  tools: [lookupOrder, approveRefund, issueRefund],
  toolChoice: 'auto',
  maxTurns: 6,
  store,
});

/** Routes each customer message to the right specialist agent. */
export const triage = ai.defineAgent({
  name: 'triage',
  system: 'Delegate order questions to orderAgent and refund requests to refundAgent. Do not answer them yourself.',
  store,
  maxTurns: 5,
  toolChoice: 'auto',
  use: [agents({ agents: ['orderAgent'], maxDelegations: 3, historyLength: 4 })],
});

/** Lets the CLI exercise triage: `genkit flow:run` runs flows, not agents. */
export const tryTriage = ai.defineFlow(
  { name: 'tryTriage', inputSchema: z.string(), outputSchema: z.string() },
  async (message) => (await triage.chat().send(message)).text,
);

/** Lets the CLI exercise the refund desk: `genkit flow:run` runs flows, not agents. */
export const tryRefundDesk = ai.defineFlow(
  { name: 'tryRefundDesk', inputSchema: z.string(), outputSchema: z.string() },
  async (message) => (await refundAgent.chat().send(message)).text,
);

import { z } from 'genkit/beta';
import { ai } from './ai.js';
import { ORDERS } from './db.js';

/** Looks up an order by id in the orders database; returns null when there is no such order. */
export const lookupOrder = ai.defineTool(
  {
    name: 'lookupOrder',
    description:
      'Looks up the status, delivery ETA, tracking code, total and refund eligibility of an order by its id, for example A-1001. ' +
      'Returns null if there is no such order.',
    inputSchema: z.object({ orderId: z.string().describe('The order id, for example A-1001') }),
    outputSchema: z
      .object({
        status: z.string(),
        eta: z.string(),
        tracking: z.string().nullable(),
        total: z.number(),
        refundable: z.boolean(),
      })
      .nullable(),
  },
  async ({ orderId }) => ORDERS[orderId.trim().toUpperCase()] ?? null,
);

import { z } from 'genkit/beta';
import { ai } from './ai.js';
import { lookupOrder } from './tools.js';

const TicketSummarySchema = z.object({
  title: z.string().describe('Short title for the ticket, under ten words'),
  priority: z.enum(['low', 'medium', 'high']).describe('How urgent the ticket is'),
  tags: z.array(z.string()).describe('Up to three lowercase topic tags'),
});

/** Turns a raw support ticket into a title, a priority and topic tags. */
export const summarizeTicket = ai.defineFlow(
  { name: 'summarizeTicket', inputSchema: z.object({ text: z.string() }), outputSchema: TicketSummarySchema },
  async ({ text }) => {
    const { output } = await ai.generate({
      system:
        'You triage support tickets for Northwind Supplies, an office supplies retailer. ' +
        'Set priority to low, medium or high, where high means the customer is blocked.',
      prompt: text,
      output: { schema: TicketSummarySchema },
    });
    if (!output) throw new Error('summarizeTicket: model returned no structured output');
    return output;
  },
);

/** Answers a customer's question about an order using the orders database. */
export const orderStatus = ai.defineFlow(
  { name: 'orderStatus', inputSchema: z.object({ question: z.string() }), outputSchema: z.string() },
  async ({ question }) => {
    const { text } = await ai.generate({
      system:
        'You are the Northwind Supplies support assistant. Answer questions about orders using the lookupOrder tool. ' +
        'Quote the status, ETA and tracking code exactly as the tool returns them. If an order is not found, say so.',
      prompt: question,
      tools: [lookupOrder],
    });
    return text;
  },
);

/** Welcomes a customer by name using the greet dotprompt. */
export const greet = ai.defineFlow(
  { name: 'greet', inputSchema: z.object({ customerName: z.string() }), outputSchema: z.string() },
  async ({ customerName }) => {
    const { text } = await ai.prompt('greet')({ customerName });
    return text;
  },
);

/** Drafts a full reply to a ticket and reports why the model stopped generating. */
export const draftReply = ai.defineFlow(
  {
    name: 'draftReply',
    inputSchema: z.object({ ticket: z.string() }),
    outputSchema: z.object({ text: z.string(), finishReason: z.string() }),
  },
  async ({ ticket }) => {
    const response = await ai.generate({
      system:
        'You are a support agent at Northwind Supplies. Draft a complete, polite reply to the customer: ' +
        'greet them, acknowledge the problem, explain the next steps in two or three sentences, and sign off as the Northwind support team.',
      prompt: ticket,
    });
    return { text: response.text, finishReason: response.finishReason };
  },
);

const ChatMessageSchema = z.object({ role: z.enum(['user', 'model']), text: z.string() });

/** Multi-turn support chat; the caller keeps the history. */
export const chat = ai.defineFlow(
  {
    name: 'chat',
    inputSchema: z.object({ history: z.array(ChatMessageSchema), message: z.string() }),
    outputSchema: z.string(),
  },
  async ({ history, message }) => {
    const { text } = await ai.generate({
      system:
        'You are the Northwind Supplies support assistant. Keep replies to one or two sentences. ' +
        'Use what the customer told you earlier in the conversation, such as their name or order id.',
      messages: history.map(({ role, text }) => ({ role, content: [{ text }] })),
      prompt: message,
    });
    return text;
  },
);

import { fileURLToPath } from 'node:url';
import { googleAI } from '@genkit-ai/google-genai';
import { genkit } from 'genkit/beta';

/** The Genkit instance every flow and agent in this app shares. */
export const ai = genkit({
  plugins: [googleAI()],
  // Thinking tokens count against maxOutputTokens, so thinking is off to let a token cap cut the reply itself.
  model: googleAI.model('gemini-2.5-flash', { temperature: 0, thinkingConfig: { thinkingBudget: 0 } }),
  promptDir: fileURLToPath(new URL('../prompts/', import.meta.url)),
});

import orders from './orders.json' with { type: 'json' };

/** Order record as the warehouse system reports it. */
export interface Order {
  status: string;
  eta: string;
  tracking: string | null;
  total: number;
  refundable: boolean;
}

/** Orders by id, from the warehouse export. */
export const ORDERS: Record<string, Order> = orders;

/** Refund issued against an order. */
export interface Refund {
  orderId: string;
  amount: number;
}

/** Refunds by id. */
export const REFUNDS: Record<string, Refund> = {};

/** Records a refund and returns its id. Throws if the order is unknown or not refundable. */
export const createRefund = (orderId: string, amount: number): string => {
  const order = ORDERS[orderId];
  if (!order) throw new Error(`Order ${orderId} not found`);
  if (!order.refundable) throw new Error(`Order ${orderId} is not refundable`);
  const refundId = `R-${1001 + Object.keys(REFUNDS).length}`;
  REFUNDS[refundId] = { orderId, amount };
  return refundId;
};

